#include "rigid.hpp"
#include <iostream>
#include <fstream>
#include <iomanip>
#include <sstream>
#include <omp.h>
using namespace rigid;
double wrapped(double a){return std::remainder(a,2*M_PI);}
int main(){struct Job{int n,mode;double h;std::string method;};std::vector<Job>jobs;for(int n:{2,3})for(int mode=0;mode<n;++mode)for(double h:{1./30,1./120})for(std::string method:{"rattle","cart_dg","sym_energy","canonical_midpoint","canonical_dg","canonical_avf","obj_quarter_b1","obj_midpotential_b1","obj_ls_dg_E"})jobs.push_back({n,mode,h,method});std::vector<std::string>rows(jobs.size());
#pragma omp parallel for schedule(dynamic)
for(int idx=0;idx<int(jobs.size());++idx){auto j=jobs[idx];Model m;m.count=j.n;m.dim=2;m.rigid=true;m.mass=V::Ones(j.n);m.length=V::Ones(j.n);m.stiffness=V::Zero(j.n);m.gravity=vec({0,-9.81});Mat A=angle_mass(m,V::Zero(j.n)),K=(9.81*suffix(m)).asDiagonal();Eigen::GeneralizedSelfAdjointEigenSolver<Mat>eig(K,A);V omega=eig.eigenvalues().cwiseSqrt();Mat basis=eig.eigenvectors();V z=V::Zero(2*j.n);z.head(j.n)=.02*basis.col(j.mode);State initial=cartesian(m,z),s=initial;Scale q=scales(m,s);double e0=energy(m,s),amp0=.02,maxE=0,maxT=0,maxleak=0,phase=0,refphase=0,prev=0,prevref=0,minamp=1e9,maxamp=0,refgap=0;int done=0,ev=0;V ref=z,ref2=z;std::string status="complete",reason;int N=std::lround(60/j.h);for(int step=0;step<N;++step){Result a=advance(m,s,j.h,q,j.method);ev+=a.evaluations;if(!a.ok){status="failed";reason=a.reason;break;}s=a.s;++done;ref=rk4(m,ref,j.h,16);ref2=rk4(m,ref2,j.h,32);refgap=std::max(refgap,(encode(cartesian(m,ref),q)-encode(cartesian(m,ref2),q)).norm());V zz=angles(m,s),modal=basis.transpose()*A*zz.head(j.n),vel=basis.transpose()*A*zz.tail(j.n),rmodal=basis.transpose()*A*ref2.head(j.n),rvel=basis.transpose()*A*ref2.tail(j.n);double aphase=std::atan2(-vel[j.mode]/omega[j.mode],modal[j.mode]),rphase=std::atan2(-rvel[j.mode]/omega[j.mode],rmodal[j.mode]);phase+=wrapped(aphase-prev);refphase+=wrapped(rphase-prevref);prev=aphase;prevref=rphase;double amplitude=std::hypot(modal[j.mode],vel[j.mode]/omega[j.mode]);minamp=std::min(minamp,amplitude/amp0);maxamp=std::max(maxamp,amplitude/amp0);double leakage=0;for(int k=0;k<j.n;++k)if(k!=j.mode)leakage+=omega[k]*omega[k]*modal[k]*modal[k]+vel[k]*vel[k];maxleak=std::max(maxleak,leakage/(omega[j.mode]*omega[j.mode]*amp0*amp0));maxE=std::max(maxE,std::abs(energy(m,s)-e0)/q.e);maxT=std::max(maxT,(gradient(m,s.x)*s.v).norm()/(q.l*q.v));}
std::ostringstream o;o<<std::setprecision(16)<<j.n<<","<<j.mode<<","<<omega[j.mode]<<","<<j.method<<","<<j.h<<","<<status<<","<<reason<<","<<done<<","<<N<<","<<phase-refphase<<","<<(phase-refphase)/(60*omega[j.mode])<<","<<minamp<<","<<maxamp<<","<<maxleak<<","<<maxE<<","<<maxT<<","<<refgap<<","<<ev;rows[idx]=o.str();}
std::ofstream out("modes.csv");out<<"links,mode,linear_frequency,method,h,status,reason,steps_done,steps_requested,phase_error_rad,relative_frequency_error,min_amplitude_ratio,max_amplitude_ratio,max_other_mode_fraction,max_energy_relative,max_tangency,reference_gap,residual_evaluations\n";for(auto&r:rows)out<<r<<"\n";std::cout<<"modal trajectories="<<rows.size()<<"\n";}
